INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES ("それに比してメ団の面々は豪胆だ、\n麦しゅわ煽って大騒ぎとは畏れ入る。\nさすが辣腕の事業家と言ったところか。\nとりわけアキノ君は貴族の出自だしな。", 1, 11, 517, 0, 517021, 0, 111031, 8, 0, 0.5);
